"""Host-side scorer for ai4bio-msa-conformational-ensemble (A-pattern).

Runs in the harness process (native) or the Harbor VERIFIER (`tests/meta/`) -- never
inside the agent container.  The fixed driver writes ONE npz of CA traces to OUTPUT_DIR
and prints a nonce-gated `FINAL_ENS` marker naming it.  The experimentally determined
conformations live in `dgp` (staged beside this file on the verifier side) and are
unreachable from the workspace, so forging the marker buys nothing: the TM-scores are
computed HERE, against structures the container never saw.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
_ROOT = _HERE.parents[1]

# `mlsbench` is pre-imported by the Harbor verifier.  Only fall back to the repo
# checkout when it is genuinely absent -- under Harbor this parser is exec'd from
# /tmp/mlsbench-verifier.XXXXXX/meta/, so a __file__-derived root is /tmp and inserting
# it would put an agent-writable directory on the verifier's sys.path.
try:
    from mlsbench.agent.parsers import OutputParser, ParseResult
except ModuleNotFoundError:  # native checkout without an install
    sys.path.insert(0, str(_ROOT / "src"))
    from mlsbench.agent.parsers import OutputParser, ParseResult
from mlsbench.holdout import load_holdout_module  # noqa: E402

# Resolve dgp through the shared loader: by explicit file path from the sealed
# locations only, never through a sys.path entry derived from __file__ or cwd.
dgp = load_holdout_module("ai4bio-msa-conformational-ensemble", __file__)

_CFG = Path(__file__).with_name("config.json")
_SEEDS = set(int(s) for s in json.loads(_CFG.read_text()).get("seeds", [42])) if _CFG.exists() else {42}
_MARKER = re.compile(
    r"^FINAL_ENS env=(?P<env>\S+) seed=(?P<seed>\d+) "
    r"(?:status=OK nonce=(?P<nonce>[0-9a-f]+) path=(?P<path>\S+)|status=INVALID rc=(?P<rc>-?\d+))\s*$")


def _refuse(msg, raw):
    return ParseResult(feedback=msg + "\n" + "\n".join(raw.splitlines()[-25:]), metrics={})


class Parser(OutputParser):
    def parse(self, cmd_label, raw_output):
        match = None
        for line in raw_output.splitlines():
            m = _MARKER.match(line.strip())
            if m is not None and m.group("env") == cmd_label:
                match = m
        if match is None:
            return _refuse(f"{cmd_label}: no FINAL_ENS marker (the fixed driver emits it).", raw_output)
        if match.group("rc") is not None:
            return _refuse(f"{cmd_label}: the driver did not complete (rc={match.group('rc')}).", raw_output)
        seed = int(match.group("seed"))
        if seed not in _SEEDS:
            return _refuse(f"{cmd_label}: seed {seed} is not one of the task seeds.", raw_output)
        path = Path(match.group("path"))
        if not path.exists():
            return _refuse(f"{cmd_label}: the driver's ensemble archive {path} is missing.", raw_output)
        try:
            with np.load(path, allow_pickle=False) as z:
                if str(z["nonce"][0]) != match.group("nonce"):
                    return _refuse(f"{cmd_label}: ensemble archive carries a stale run token.", raw_output)
                if str(z["setting"][0]) != cmd_label:
                    return _refuse(f"{cmd_label}: archive was produced for another setting.", raw_output)
                per_target, missing = {}, []
                for target in dgp.targets(cmd_label):
                    token = dgp.opaque_label(cmd_label, target)
                    key = f"{token}|n"
                    if key not in z:
                        missing.append(target); continue
                    n = int(z[key][0])
                    if n != dgp.BUDGET:
                        # The driver enforces the budget; an archive that disagrees was
                        # not produced by the fixed driver's honest path.
                        return _refuse(f"{cmd_label}: {n} predictions for one target, the "
                                       f"budget is {dgp.BUDGET}; refusing the archive.", raw_output)
                    rows = []
                    for k in range(n):
                        xyz = np.asarray(z[f"{token}|{k}|xyz"], dtype=np.float64)
                        seq = bytes(z[f"{token}|{k}|seq"]).decode()
                        rows.append(dgp.tm_to_states(xyz, seq, cmd_label, target))
                    per_target[target] = rows
        except Exception as exc:
            return _refuse(f"{cmd_label}: could not read the ensemble archive ({exc}).", raw_output)
        if not per_target:
            return _refuse(f"{cmd_label}: the archive holds no predictions.", raw_output)

        res = dgp.score_predictions(cmd_label, per_target)
        rule, thr, cite = dgp.RULES[cmd_label]
        n_pred = int(np.mean([len(v) for v in per_target.values()])) if per_target else 0
        lines = [f"{cmd_label}: {res['n_targets']} targets, {n_pred} predictions/target; "
                 f"both states recovered for {int(round(res['recovery_rate']*res['n_targets']))}"
                 f"/{res['n_targets']} ({res['recovery_rate']:.1%}); "
                 f"mean min-best TM {res['mean_min_best_tm']:.4f}  [rule: {rule} @ {thr}, {cite}]"]
        for t, r in sorted(res["per_target"].items()):
            lines.append(f"    {t:22s} n={r['n']:4d} best {r['best1']:.3f}/{r['best2']:.3f} "
                         f"{'RECOVERED' if r['recovered'] else '-'}")
        if missing:
            lines.append(f"    (no predictions for: {', '.join(missing)})")
        return ParseResult(feedback="\n".join(lines), metrics={
            f"recovery_{cmd_label}": 100.0 * res["recovery_rate"],
            f"minbesttm_{cmd_label}": res["mean_min_best_tm"],
        })
